import { compactScore } from './data/formatScore';
import { BenchmarkHeading } from './components/BenchmarkHeading';
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from 'react';
import { columnVisibilityFeature, flexRender, rowSortingFeature, tableFeatures, useTable, type ColumnDef, type SortingState } from '@tanstack/react-table';
import { ArrowDown, ArrowDownUp, ArrowUp, ChevronDown, ChevronRight, Download, ExternalLink, Filter, Search, Share2, SlidersHorizontal, X } from 'lucide-react';
import type { AppData } from './data/snapshots';
import { loadSnapshots, loadEvidence, type FullAppData } from './data/snapshots';
import { benchmarkSearchForView, otherConfigurationResults, otherConfigurationScores, categoryLabels, hasResultOnBenchmarks, numeric, numericScoreCount, orderColumnsByModelCoverage, presetIncludesAllModels, type DisplayRow } from './data/selectors';
import { scoreRanges, scoreColor, isBestScore, type ScoreRange } from './data/heatmap';
import { useViewRows } from './data/useViewRows';
import { useColumnCapacity, MODEL_COLUMN_WIDTH, DATA_COLUMN_WIDTH } from './data/useColumnCapacity';
import type { BenchmarkVariant, ModelRelease, Observation, PriceObservation, Source } from './generated/dataset';
import { TransposedTable } from './components/TransposedTable';
import { PortraitComparison } from './components/PortraitComparison';
import { HeaderTooltip } from './components/HeaderTooltip';
import { ModelPicker } from './components/ModelPicker';
import { ModelIdentity } from './components/ModelIdentity';
import { Badge } from './components/ui/badge';
import { Button } from './components/ui/button';
import { Checkbox } from './components/ui/checkbox';
import { Input } from './components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './components/ui/select';
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from './components/ui/sheet';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from './components/ui/table';
